/* --- POWERFUL EXPRESS UTILITIES --- */

// REQUEST (req) superpowers:
// req.body       -> The parsed JSON payload from the client
// req.cookies    -> An object of cookies sent by the browser
// req.ip         -> The client's IP address
// req.get('host') -> Easily read a specific header

// RESPONSE (res) superpowers:
// res.json({ id: 1 }) -> Automatically stringifies and sets JSON headers
// res.status(404)     -> Chains nicely: res.status(404).json(...)
// res.redirect('/login') -> Instantly redirects the browser
// res.download('/files/report.pdf') -> Prompts a file download
// res.cookie('token', '1234') -> Sets a cookie in the browser

console.log("Express removes 90% of the boilerplate required to format HTTP communications.");
